     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        Room room = rooms.find(request.roomNumber())
    35	                .orElseThrow(() -> new HotelException(
    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    37	        if (request.guests() > room.capacity()) {
    38	            throw new HotelException(
    39	                    ErrorCode.CAPACITY_EXCEEDED,
    40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    41	        }
    42	        Price price = priceCalculator.calculate(room, request);
    43	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    44	            throw new HotelException(
    45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    46	        }
    47	        return store.add(request, price);
    48	    }
    49	
    50	    public Reservation find(long reservationId) {
    51	        return store.find(reservationId)
    52	                .orElseThrow(() -> new HotelException(
    53	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    54	    }
    55	
    56	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    57	    public synchronized Reservation confirm(long reservationId) {
    58	        Reservation reservation = find(reservationId);
    59	        if (reservation.status() != ReservationStatus.PENDING) {
    60	            throw notAllowed(reservation, "confirm");
    61	        }
    62	        reservation.confirmPayment();
    63	        store.update(reservation);
    64	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    65	        emailSender.send(
    66	                reservation.guest().email(),
    67	                "Reserva confirmada - " + HOTEL_NAME,
    68	                confirmationEmailBody(reservation, receipt));
    69	        return reservation;
    70	    }
    71	
    72	    /**
    73	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    74	     * reservation was never paid, so nothing comes back).
    75	     */
    76	    public synchronized Reservation cancel(long reservationId) {
    77	        Reservation reservation = find(reservationId);
    78	        if (reservation.status() != ReservationStatus.PENDING
    79	                && reservation.status() != ReservationStatus.CONFIRMED) {
    80	            throw notAllowed(reservation, "cancel");
    81	        }
    82	        BigDecimal refund = reservation.ratePlan().refund(reservation.amountPaid());
    83	        reservation.cancel(refund);
    84	        store.update(reservation);
    85	        return reservation;
    86	    }
    87	
    88	    public synchronized Reservation checkIn(long reservationId) {
    89	        Reservation reservation = find(reservationId);
    90	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    91	            throw notAllowed(reservation, "check in");
    92	        }
    93	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    94	        store.update(reservation);
    95	        return reservation;
    96	    }
    97	
    98	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
    99	    public synchronized ReservationReceipt checkOut(long reservationId) {
   100	        Reservation reservation = find(reservationId);
   101	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   102	            throw notAllowed(reservation, "check out");
   103	        }
   104	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   105	        store.update(reservation);
   106	        return new ReservationReceipt(reservation, roomOf(reservation));
   107	    }
   108	
   109	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   110	    public ReservationReceipt receiptCopy(long reservationId) {
   111	        Reservation reservation = find(reservationId);
   112	        if (!reservation.isPaid()) {
   113	            throw notAllowed(reservation, "issue a receipt for");
   114	        }
   115	        return new ReservationReceipt(reservation, roomOf(reservation));
   116	    }
   117	
   118	    private Room roomOf(Reservation reservation) {
   119	        return rooms.find(reservation.roomNumber()).orElseThrow();
   120	    }
   121	
   122	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   123	        return "Olá, " + reservation.guest().name() + "!\n\n"
   124	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   125	                + receipt.text() + "\n"
   126	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   127	                + "Até breve!\n";
   128	    }
   129	
   130	    private static HotelException notAllowed(Reservation reservation, String operation) {
   131	        return new HotelException(
   132	                ErrorCode.OPERATION_NOT_ALLOWED,
   133	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   134	    }
   135	}
     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	
     9	/**
    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    11	 * high-season nights; the rate plan then prices the stay (a discount, a closed price) or rejects it. Money is rounded to cents
    12	 * (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	
    18	    public Price calculate(Room room, NewReservation request) {
    19	        int nights = 0;
    20	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    21	        for (LocalDate night = request.checkIn(); night.isBefore(request.checkOut()); night = night.plusDays(1)) {
    22	            subtotal = subtotal.add(nightPrice(room, night));
    23	            nights++;
    24	        }
    25	        Price base = new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
    26	        return request.ratePlan().price(room, request, base);
    27	    }
    28	
    29	    BigDecimal nightPrice(Room room, LocalDate night) {
    30	        BigDecimal nightlyRate = room.nightlyRate();
    31	        if (isHighSeason(night)) {
    32	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    33	        }
    34	        return cents(nightlyRate);
    35	    }
    36	
    37	    /** High season: from December 15 to the end of February, and the whole of July. */
    38	    static boolean isHighSeason(LocalDate date) {
    39	        Month month = date.getMonth();
    40	        return month == Month.JANUARY
    41	                || month == Month.FEBRUARY
    42	                || month == Month.JULY
    43	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    44	    }
    45	
    46	    static BigDecimal cents(BigDecimal value) {
    47	        return value.setScale(2, RoundingMode.HALF_EVEN);
    48	    }
    49	}
