@Override
public Price price(Room room, NewReservation request, Price base) {
    BigDecimal discount = request.companyCode() == null ? null : DISCOUNT_BY_COMPANY.get(request.companyCode());
    if (discount == null) {
        throw new HotelException(
                ErrorCode.INVALID_REQUEST, "the corporate plan needs the code of a company with an agreement");

@Test
void corporateNeedsAKnownCompanyCode() {
    for (String code : new String[] {null, "", "tecnosul", "OUTRA"}) {
        assertEquals(ErrorCode.INVALID_REQUEST, rejection(() -> priceWithCompany(
                deluxe, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, code)));
    }
}

